CREATE TRIGGER movements_insert BEFORE INSERT ON movements BEGIN
 SELECT RAISE(ABORT,'movement_account') WHERE NOT EXISTS (SELECT 1 FROM accounts WHERE id=NEW.account_id AND kind='account' AND substr(NEW.value_date,1,7)||'-01'>=active_from AND (active_through IS NULL OR substr(NEW.value_date,1,7)||'-01'<=active_through));
 SELECT RAISE(ABORT,'movement_origin') WHERE NEW.import_row_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM import_rows WHERE id=NEW.import_row_id AND record_kind='movement');
END;

CREATE TRIGGER movements_update BEFORE UPDATE ON movements BEGIN
 SELECT RAISE(ABORT,'movement_account') WHERE NOT EXISTS (SELECT 1 FROM accounts WHERE id=NEW.account_id AND kind='account' AND substr(NEW.value_date,1,7)||'-01'>=active_from AND (active_through IS NULL OR substr(NEW.value_date,1,7)||'-01'<=active_through));
 SELECT RAISE(ABORT,'movement_origin_immutable') WHERE NEW.import_row_id IS NOT OLD.import_row_id;
END;

CREATE TRIGGER accounts_movement_bounds BEFORE UPDATE OF active_from,active_through ON accounts BEGIN
 SELECT RAISE(ABORT,'movement_bounds') WHERE EXISTS (SELECT 1 FROM movements WHERE account_id=NEW.id AND (substr(value_date,1,7)||'-01'<NEW.active_from OR (NEW.active_through IS NOT NULL AND substr(value_date,1,7)||'-01'>NEW.active_through)));
END;

CREATE TRIGGER categories_insert BEFORE INSERT ON categories BEGIN
 SELECT RAISE(ABORT, 'category_cycle') WHERE NEW.parent_id=NEW.id OR EXISTS (
 WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.parent_id
 UNION SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
 ) SELECT 1 FROM ancestors WHERE id=NEW.id);
 SELECT RAISE(ABORT, 'category_depth') WHERE (
 WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.parent_id
 UNION ALL SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
 ) SELECT count(*) FROM ancestors
 ) + (
 WITH RECURSIVE descendants(id,depth) AS (
 SELECT NEW.id,1 UNION ALL SELECT c.id,d.depth+1 FROM categories c JOIN descendants d ON c.parent_id=d.id
 ) SELECT max(depth) FROM descendants
 ) > 3;
END;

CREATE TRIGGER categories_update BEFORE UPDATE OF parent_id ON categories BEGIN
 SELECT RAISE(ABORT, 'category_cycle') WHERE NEW.parent_id=NEW.id OR EXISTS (
 WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.parent_id
 UNION SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
 ) SELECT 1 FROM ancestors WHERE id=NEW.id);
 SELECT RAISE(ABORT, 'category_depth') WHERE (
 WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.parent_id
 UNION ALL SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
 ) SELECT count(*) FROM ancestors
 ) + (
 WITH RECURSIVE descendants(id,depth) AS (
 SELECT NEW.id,1 UNION ALL SELECT c.id,d.depth+1 FROM categories c JOIN descendants d ON c.parent_id=d.id
 ) SELECT max(depth) FROM descendants
 ) > 3;
END;

CREATE TRIGGER account_kind_immutable BEFORE UPDATE OF kind ON accounts WHEN NEW.kind<>OLD.kind BEGIN
 SELECT RAISE(ABORT,'account_kind_immutable');
END;

CREATE TRIGGER budgets_insert BEFORE INSERT ON budgets BEGIN SELECT RAISE(ABORT,'budget_overlap') WHERE EXISTS (WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.category_id
 UNION ALL SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
), descendants(id) AS (
 SELECT NEW.category_id UNION ALL SELECT c.id FROM categories c JOIN descendants d ON c.parent_id=d.id
) SELECT 1 FROM budgets b WHERE b.month=NEW.month AND b.id<>NEW.id
AND (b.category_id IN (SELECT id FROM ancestors) OR b.category_id IN (SELECT id FROM descendants)));
SELECT RAISE(ABORT,'budget_origin') WHERE NEW.import_row_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM import_rows WHERE id=NEW.import_row_id AND record_kind='budget');
END;

CREATE TRIGGER budgets_update BEFORE UPDATE ON budgets BEGIN SELECT RAISE(ABORT,'budget_overlap') WHERE EXISTS (WITH RECURSIVE ancestors(id,parent_id) AS (
 SELECT id,parent_id FROM categories WHERE id=NEW.category_id
 UNION ALL SELECT c.id,c.parent_id FROM categories c JOIN ancestors a ON c.id=a.parent_id
), descendants(id) AS (
 SELECT NEW.category_id UNION ALL SELECT c.id FROM categories c JOIN descendants d ON c.parent_id=d.id
) SELECT 1 FROM budgets b WHERE b.month=NEW.month AND b.id<>NEW.id
AND (b.category_id IN (SELECT id FROM ancestors) OR b.category_id IN (SELECT id FROM descendants)));
SELECT RAISE(ABORT,'budget_origin_immutable') WHERE NEW.import_row_id IS NOT OLD.import_row_id;
END;

CREATE TRIGGER categories_promotion BEFORE UPDATE OF parent_id,is_income ON categories
WHEN OLD.parent_id IS NOT NULL AND NEW.parent_id IS NULL BEGIN
 SELECT RAISE(ABORT,'category_promotion_type') WHERE NEW.is_income IS NOT (
 WITH RECURSIVE ancestors(id,parent_id,is_income) AS (
 SELECT id,parent_id,is_income FROM categories WHERE id=OLD.parent_id
 UNION SELECT c.id,c.parent_id,c.is_income FROM categories c JOIN ancestors a ON c.id=a.parent_id
 ) SELECT is_income FROM ancestors WHERE parent_id IS NULL);
END;

CREATE TRIGGER categories_destination_insert BEFORE INSERT ON categories
WHEN NEW.parent_id IS NOT NULL BEGIN
 SELECT RAISE(ABORT,'category_destination') WHERE NOT EXISTS (
 SELECT 1 FROM categories WHERE id=NEW.parent_id AND archived=0);
END;

CREATE TRIGGER categories_destination_update BEFORE UPDATE OF parent_id ON categories
WHEN NEW.parent_id IS NOT NULL AND NEW.parent_id IS NOT OLD.parent_id BEGIN
 SELECT RAISE(ABORT,'category_destination') WHERE NOT EXISTS (
 SELECT 1 FROM categories WHERE id=NEW.parent_id AND archived=0);
END;

CREATE TRIGGER categories_budget_overlap AFTER UPDATE OF parent_id ON categories
WHEN NEW.parent_id IS NOT OLD.parent_id BEGIN
 SELECT RAISE(ABORT,'category_budget_overlap') WHERE EXISTS (
 WITH RECURSIVE ancestry(id,ancestor) AS (
 SELECT id,parent_id FROM categories WHERE parent_id IS NOT NULL
 UNION SELECT a.id,c.parent_id FROM ancestry a JOIN categories c ON c.id=a.ancestor WHERE c.parent_id IS NOT NULL
 ) SELECT 1 FROM budgets b JOIN ancestry a ON a.id=b.category_id
 JOIN budgets p ON p.category_id=a.ancestor AND p.month=b.month);
END;
